def create_default_typer(
    panel_name: str,
    field: FieldInfo,
    *,
    prompt_always: bool = False,
) -> str:
    """Create the default value for pydantic ModelFields for typer functions."""
    prompt = ""
    if prompt_always:
        prompt = ", prompt=True"
    if getattr(field, "is_required", False):
        default = "=None"
    elif field.default is None:
        default = f' = typer.Option(None, help="{field.description or ""}", rich_help_panel="{panel_name}"{prompt})'
    elif field.default is PydanticUndefined:
        default = f' = typer.Option(..., help="{field.description or ""}", rich_help_panel="{panel_name}", prompt=True)'
    else:
        default = f' = typer.Option("{field.default}", help="{field.description or ""}", rich_help_panel="{panel_name}"{prompt})'
    return default

